&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_একটি_কাজের_সম্পূর্ণ_জীবন_চক্র&quot;&gt;একটি কাজের সম্পূর্ণ জীবন-চক্র&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 8) ]

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

title শেল কাজের সম্পূর্ণ জীবন চক্র
state &quot;অস্তিত্বহীন&quot; as none
state &quot;অগ্রভূমি\n(টার্মিনালকে اشغال করে)&quot; as foreground #LightCoral
state &quot;বন্ধ
^^^^^
 Syntax Error? (Assumed diagram type: state)

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

title শেল কাজের সম্পূর্ণ জীবন চক্র
state &quot;অস্তিত্বহীন&quot; as none
state &quot;অগ্রভূমি\n(টার্মিনালকে اشغال করে)&quot; as foreground #LightCoral
state &quot;বন্ধ
(Ctrl+Z / SIGTSTP)&quot; as suspended #LightYellow
state &quot;পটভূমি\n(bg অথবা &amp;amp;)&quot; as background #LightGreen
state &quot;সমাপ্ত\n(exit code 0)&quot; as done #LightGray

[*] --&amp;gt; none
none --&amp;gt; foreground : tape une commande
foreground --&amp;gt; suspended : Ctrl+Z
foreground --&amp;gt; done : fin normale

suspended --&amp;gt; foreground : fg
suspended --&amp;gt; background : bg
suspended --&amp;gt; done : kill %n

background --&amp;gt; foreground : fg
background --&amp;gt; done : fin normale\n(en arrière-plan)
background --&amp;gt; suspended : Ctrl+Z\n(si fg puis Ctrl+Z)

done --&amp;gt; [*]

note right of suspended
  L&#39;état suspendu est
  le pivot de tout le
  système de jobs
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_উন্নত_টিপস&quot;&gt;উন্নত টিপস&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fg_সঙ্গে_সবচেয়ে_নতুন_চাকরি_এবং_বিনিময়&quot;&gt;fg সঙ্গে সবচেয়ে নতুন চাকরি এবং বিনিময়&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;fg`আর্গুমেন্ট ছাড়াই চিহ্নিত করা কাজটি আনে&lt;/code&gt;+&lt;code&gt;(সর্বশেষ). আপনি এটাও ব্যবহার করতে পারেন&lt;/code&gt;%-`আগের কাজটি লক্ষ্য করতে :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ vim file1.txt
^Z
[1]+  Stoppé    vim file1.txt

$ vim file2.txt
^Z
[2]+  Stoppé    vim file2.txt

$ fg      # ramène job [2] (le plus récent)
$ fg %-   # ramène job [1] (le précédent)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_কामকে_পরিষ্কারভাবে_শেষ_করা&quot;&gt;কामকে পরিষ্কারভাবে শেষ করা&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ jobs
[1]-  Stoppé    vim config.yml
[2]+  Stoppé    ./gradlew test

$ kill %2       # envoie SIGTERM au job 2
$ kill -9 %1    # envoie SIGKILL au job 1 (force)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_désown_শেল_থেকে_ডিট্যাচ_করুন&quot;&gt;désown : শেল থেকে ডিট্যাচ করুন&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;disown`একটি job শেলের job টেবিল থেকে সরানো হয়। প্রক্রিয়া চলছে কিন্তু এখনও আর এর সাথে ফেরত আনা যায় না সঙ্গে`fg&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build &amp;amp;
[1] 12345

$ disown %1
# Le processus continue mais n&#39;est plus lié au shell
# Ça survives à la fermeture du terminal&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_দীর্ঘস্থায়ী_প্রক্রিয়াগুলোর_জন্য_nohup_এর_সাথে_মিশ্রিত_করুন&quot;&gt;দীর্ঘস্থায়ী প্রক্রিয়াগুলোর জন্য nohup-এর সাথে মিশ্রিত করুন&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;একটি প্রক্রিয়া টার্মিনাল বন্ধ হওয়ার পরেও বাঁচতে পারে :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ nohup ./gradlew build &amp;amp;
[1] 12345
$ disown %1
# Le build continue même si vous fermez le terminal&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;Failed to generate image: PlantUML preprocessing failed: [From &amp;lt;input&amp;gt; (line 7) ]

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;fg&quot; as fg_ #SkyBlue {
  card &quot;কাজটি আনো
সর্বশেষটি (+)&quot; as f1
^^^^^
 Syntax Error? (Assumed diagram type: activity)

@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;fg&quot; as fg_ #SkyBlue {
  card &quot;কাজটি আনো
সর্বশেষটি (+)&quot; as f1
  card &quot;একটি নির্দিষ্ট কাজ লক্ষ্য করুন\nfg %n&quot; as f2
  card &quot;বিকল্প: fg %-%&quot; as f3
}

rectangle &quot;%n-কে হত্যা কর&quot; as kill_ #LightCoral {
  card &quot;SIGTERM (পরিষ্কার)&quot; as k1
  card &quot;SIGKILL -9 (বল)&quot; as k2
}

rectangle &quot;অস্বীকার&quot; as disown #Lavender {
  card &quot;শেল থেকে পৃথক করুন
(বন্ধকরণে জীবন্ত থাকা)&quot; as d1
}

rectangle &quot;nohup + &amp;amp;&quot; as nohup_ #LightGreen {
  card &quot;SIGHUP-কে প্রতিরোধী প্রক্রিয়া (টার্মিনাল বন্ধ হওয়ার পর জীবিত থাকে)&quot; as n1
}

fg_ -right-&amp;gt; kill_ : si faut\nterminer
kill_ -right-&amp;gt; disown_ : ou détacher
nohup_ -left-&amp;gt; fg_ : fg ramène en\navant-plan

note bottom of disown_
  Après disown, fg ne peut
  plus ramener le job
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_সাধারন_ব্যাহতি_ও_ভุล&quot;&gt;সাধারন ব্যাহতি ও ভุล&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ctrlz_এবং_ctrlc_বুলিয়ে_নেওয়া&quot;&gt;Ctrl+Z এবং Ctrl+C বুলিয়ে নেওয়া&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;এটি সবচেয়ে সচরাচর ত্রুটি।`Ctrl+C`প্রক্রিয়া মārন করে।`Ctrl+Z`এইকে বন্ধ করে। আপনি চাপ দিলে`Ctrl+C`প্রতিভাবনে, সকল অবস্থা হারিয়ে যায় — খোলা ফাইল, LLM সেশন, চলমান বিল্ড।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;imageblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;img src=&quot;./images/ctrlz-vs-ctrlc.svg&quot; alt=&quot;ctrlz vs ctrlc&quot; width=&quot;1257&quot; height=&quot;129&quot;&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_জবগুলো_শেলের_জন্য_স্থানীয়&quot;&gt;জবগুলো শেলের জন্য স্থানীয়&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;jobs&lt;/code&gt;, &lt;code&gt;fg&lt;/code&gt; et `bg`তারা শুধুমাত্র সেই শেলে কাজ করে যা প্রক্রিয়াগুলি চালিয়েছিল। আপনি যদি একটি নতুন টার্মিনাল খুলেন, আপনি অন্যের কাজগুলো দেখবেন না।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Terminal 1
$ vim file.txt
^Z
[1]+  Stoppé    vim file.txt

# Terminal 2 (nouveau)
$ jobs
# (rien — les jobs sont locaux au shell)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;সিস্টেম-wide প্রক্রিয়া দেখতে, ব্যবহার করুন`ps` ou &lt;code&gt;htop&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;ps aux | grep vim&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_শেল_বন্ধ_হলে_জবস_suriname_করে_না&quot;&gt;শেল বন্ধ হলে জবস Suriname করে না&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;আপনি যদি টার্মিনাল বন্ধ করেন, তাহলে বিলম্বিত বা ব্যাকগ্রাউন্ডে চলমান সমস্ত কাজ নাশিত হয়। একটি প্রক্রিয়া জীবিত রাখতে, ব্যবহার করুন`nohup`+&lt;code&gt;disown&lt;/code&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ nohup ./gradlew build &amp;amp;
[1] 12345
$ disown %1
# Fermer le terminal → le build continue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ইন্টারঅ্যাক্টিভ_প্রক্রিয়াগুলো_এবং_fg&quot;&gt;ইন্টারঅ্যাক্টিভ প্রক্রিয়াগুলো এবং fg&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;কতগুলো ইন্টারঅ্যাক্টিভ প্রোগ্রাম ভালো না চলছে একটি`Ctrl+Z`+&lt;code&gt;fg&lt;/code&gt;.এটা দুর্ল্ভ কিন্তু ঘটে:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;কয়েকটি প্রোগ্রাম যা সিগন্যাল ব্যবহার করে (vim, htop, less ভালভাবে পরিচালনা করেন`Ctrl+Z`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;লম্বা নেটওয়ার্ক প্রোগ্রাম (ssh, opencode) সাধারণত সঠিকভাবে পুনরুদ্ধার করে&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;টার্মিনালকে পরিবর্তনকারী প্রোগ্রাম (ncurses) কখনো কখনো টার্মিনালকে একটি অপ্রত্যাশিত অবস্থায় রেখে দিতে পারে।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;একটি দুষ্ট টার্মিনালের পর একটি`fg`, টাইপ করুন:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;reset&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_সারসংক্ষেপ_ডায়াগ্রাম&quot;&gt;সারসংক্ষেপ ডায়াগ্রাম&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
