&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;প্রেরিত_by&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;প্রভাব&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
