&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;kill -9 %n&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;বাধ্য সমাপ্তি (অব্যাহত্য)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
