&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_সমস্যা&quot;&gt;সমস্যা&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code আপডেট হলে, তা ইনস্টলেশন ফোল্ডারটি প্রতিস্থাপন করে এবং&lt;strong&gt;সকল CSS প্যাচ মুছে ফেলে&lt;/strong&gt;প্রতিবার ম্যানুয়ালি পরিবর্তনগুলো পুনরায় প্রয়োগ করতে হবে।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_স্ক্রিপ্ট_vscode_update_sh&quot;&gt;স্ক্রিপ্ট `vscode-update.sh&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;একজন তৈরি করে`~/apps/vscode-update.sh` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;#!/bin/bash
set -e

VSCODE_DIR=&quot;$HOME/apps/VSCode-linux-x64&quot;
BACKUP_DIR=&quot;$HOME/apps/vscode-backup&quot;
TEMP_DIR=&quot;/tmp/vscode-update&quot;

MENUBAR_FONT_SIZE=&quot;23px&quot;
DROPDOWN_FONT_SIZE=&quot;22px&quot;

echo &quot;=== VS Code Local Updater ===&quot;

CURRENT_VERSION=$(&quot;$VSCODE_DIR/bin/code&quot; --version 2&amp;gt;/dev/null | head -1)
echo &quot;Current version: $CURRENT_VERSION&quot;

echo &quot;Downloading latest VS Code...&quot;
mkdir -p &quot;$TEMP_DIR&quot;
wget -q &quot;https://code.visualstudio.com/sha/download?build=stable&amp;amp;os=linux-x64&quot; \
    -O &quot;$TEMP_DIR/vscode.tar.gz&quot;

echo &quot;Extracting...&quot;
mkdir -p &quot;$TEMP_DIR/extracted&quot;
tar -xzf &quot;$TEMP_DIR/vscode.tar.gz&quot; -C &quot;$TEMP_DIR/extracted&quot;

NEW_VERSION=$(&quot;$TEMP_DIR/extracted/VSCode-linux-x64/bin/code&quot; \
    --version 2&amp;gt;/dev/null | head -1)
echo &quot;New version: $NEW_VERSION&quot;

if [ &quot;$CURRENT_VERSION&quot; = &quot;$NEW_VERSION&quot; ]; then
    echo &quot;Already up to date!&quot;
    rm -rf &quot;$TEMP_DIR&quot;
    exit 0
fi

echo &quot;Backing up current installation...&quot;
mkdir -p &quot;$BACKUP_DIR&quot;
cp -r &quot;$VSCODE_DIR&quot; &quot;$BACKUP_DIR/VSCode-linux-x64-$(date +%Y%m%d-%H%M%S)&quot;

echo &quot;Updating...&quot;
rm -rf &quot;$VSCODE_DIR&quot;
mv &quot;$TEMP_DIR/extracted/VSCode-linux-x64&quot; &quot;$VSCODE_DIR&quot;
rm -rf &quot;$TEMP_DIR&quot;

CSS_FILE=&quot;$VSCODE_DIR/resources/app/out/vs/workbench/workbench.desktop.main.css&quot;
echo &quot;Re-applying custom CSS patch \
    (menubar=${MENUBAR_FONT_SIZE}, dropdown=${DROPDOWN_FONT_SIZE})...&quot;
cat &amp;gt;&amp;gt; &quot;$CSS_FILE&quot; &amp;lt;&amp;lt; CSSEOF
.menubar-menu-title{font-size:${MENUBAR_FONT_SIZE}!important}\
.menubar&amp;gt;.menubar-menu-button{font-size:${MENUBAR_FONT_SIZE}!important}\
.monaco-menu-option{font-size:${DROPDOWN_FONT_SIZE}!important;\
line-height:34px!important}\
.monaco-menu .action-label:not(.codicon)\
{font-size:${DROPDOWN_FONT_SIZE}!important}\
.menubar-menu-items-holder .monaco-menu .action-item .action-label\
{font-size:${DROPDOWN_FONT_SIZE}!important}
CSSEOF

PRODUCT_JSON=&quot;$VSCODE_DIR/resources/app/product.json&quot;
if [ -f &quot;$PRODUCT_JSON&quot; ]; then
    echo &quot;Removing checksums to prevent integrity warning...&quot;
    python3 -c &quot;
import json
with open(&#39;$PRODUCT_JSON&#39;,&#39;r&#39;) as f: data=json.load(f)
data.pop(&#39;checksums&#39;, None)
with open(&#39;$PRODUCT_JSON&#39;,&#39;w&#39;) as f: json.dump(data,f,indent=2)
print(&#39;Done.&#39;)
&quot;
fi

echo &quot;=== Update complete: $CURRENT_VERSION -&amp;gt; $NEW_VERSION ===&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;স্ক্রিপ্ট :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;সর্বশেষ স্থির সংস্করণটি ডাউনলোড করুন&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;জাচ করো যে সংস্করণ বর্তমান থেকে ভিন্ন কি না&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;বর্তমান ইনস্টলেশন (টাইমস্ট্যাম্পকৃত) ব্যাকআপ করুন`~/apps/vscode-backup/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ইনস্টলেশন ফোল্ডার বদলে দাও&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;পুনরায় প্রয়োগ কর&lt;/strong&gt;প্রধান মেনু CSS প্যাচ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;চেকসামগুলো মুছুন&lt;/strong&gt; de `product.json`ইন্টিগ্রিটি সতর্কতা এড়াতে&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
এক্সপ্লোরার প্যানের কাস্টমাইজেশনগুলো কাস্টম CSS এক্সটেনশন এবং ফাইলের&amp;lt;/tool_call&amp;gt;`~/.vscode-custom-css/custom.css`আপডেটে বাঁচে থাকেন কারণ তারা ইনস্টলেশনের ফোল্ডারের বাইরে বাস করে।
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
